import stylesText from './exercise-session-card.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';
import type { Exercise, ExerciseMaxSet, StrengthSet } from '@motivation/shared';
import {
    HEALTH_EVENTS,
    type StrengthSetCompleteEvent,
    createExerciseLateralityToggleEvent,
    createExerciseRemoveFromSessionEvent,
    createStrengthSetAddRequestEvent,
} from '../health-events.js';
import '../strength-set-row/strength-set-row.component.js';
import type { StrengthSetRow } from '../strength-set-row/strength-set-row.component.js';
import '../rest-timer/rest-timer.component.js';
import type { RestTimer } from '../rest-timer/rest-timer.component.js';

const styles = cssStyleSheet(stylesText);

/**
 * Rest between sets when the set itself carries no `rest_s` — which is every
 * hand-added set, since nothing in the UI writes that column. Story 288: the
 * timer had never once been able to fire, because `rest_s ?? 0` is 0 and the
 * card only started on `> 0`. Only a template-expanded session ever set it.
 */
const DEFAULT_REST_S = 180;

const template = document.createElement('template');
template.innerHTML = `
    <div class="card" part="card">
        <div class="card__header">
            <h3 class="card__title"></h3>
            <div class="card__header-actions">
                <button class="card__laterality" type="button" aria-pressed="false"></button>
                <button class="card__remove" type="button">Remove exercise</button>
            </div>
        </div>
        <button class="card__max" type="button" hidden></button>
        <div class="sets-list" part="sets-list"></div>
        <div class="card__footer">
            <button class="add-set-btn" type="button">+ Add set</button>
            <rest-timer></rest-timer>
        </div>
    </div>
`;

/**
 * Groups all `strength_sets` rows for one exercise inside a workout session.
 * Owns the rest timer near the next pending set — listens to its own rows'
 * STRENGTH_SET_COMPLETE event and starts the timer.
 *
 * Story 288 adds the MAX line (the record to chase, tappable to fill the next
 * unfilled row) and the both-arms ↔ one-arm toggle. The toggle lives here
 * rather than in the exercise library because here is where you are standing
 * when you notice it is wrong.
 */
export class ExerciseSessionCard extends HTMLElement {
    private exerciseValue: Exercise | null = null;
    private setsValue: StrengthSet[] = [];
    private previousByExercise: StrengthSet[] = [];
    private maxValue: ExerciseMaxSet | null = null;
    private titleNode!: HTMLElement;
    private maxBtn!: HTMLButtonElement;
    private lateralityBtn!: HTMLButtonElement;
    private setsList!: HTMLElement;
    private addBtn!: HTMLButtonElement;
    private removeBtn!: HTMLButtonElement;
    private restTimer!: RestTimer;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        this.titleNode = shadow.querySelector('.card__title') as HTMLElement;
        this.maxBtn = shadow.querySelector('.card__max') as HTMLButtonElement;
        this.lateralityBtn = shadow.querySelector('.card__laterality') as HTMLButtonElement;
        this.setsList = shadow.querySelector('.sets-list') as HTMLElement;
        this.addBtn = shadow.querySelector('.add-set-btn') as HTMLButtonElement;
        this.removeBtn = shadow.querySelector('.card__remove') as HTMLButtonElement;
        this.restTimer = shadow.querySelector('rest-timer') as RestTimer;

        // Listeners on own shadow DOM — attach once in the constructor so a
        // disconnect/reconnect cycle doesn't double-bind them. No cleanup
        // needed because the listener targets live and die with this element.
        this.addBtn.addEventListener('click', () => this.emitAddSet());
        this.removeBtn.addEventListener('click', () => this.emitRemoveExercise());
        this.maxBtn.addEventListener('click', () => this.fillNextUnfilledFromMax());
        this.lateralityBtn.addEventListener('click', () => this.emitLateralityToggle());
        this.setsList.addEventListener(HEALTH_EVENTS.STRENGTH_SET_COMPLETE, (e: StrengthSetCompleteEvent) => {
            this.restTimer.start(e.detail.rest_s ?? DEFAULT_REST_S);
        });
    }

    set exercise(value: Exercise) {
        this.exerciseValue = value;
        this.render();
    }

    get exercise(): Exercise | null {
        return this.exerciseValue;
    }

    set sets(value: StrengthSet[]) {
        this.setsValue = [...value].sort((a, b) => a.set_index - b.set_index);
        this.renderSets();
    }

    /** Every set of the previous session for this exercise — feeds the prev column. */
    set previousSets(value: StrengthSet[]) {
        this.previousByExercise = value;
        this.renderSets();
    }

    /** The heaviest set ever logged, or null when there is no history. */
    set maxSet(value: ExerciseMaxSet | null) {
        this.maxValue = value;
        this.renderMax();
    }

    connectedCallback(): void {
        this.render();
    }

    private render(): void {
        if (!this.exerciseValue) return;
        this.titleNode.textContent = this.exerciseValue.display_name;
        this.renderLaterality();
        this.renderMax();
        this.renderSets();
    }

    private renderSets(): void {
        if (!this.exerciseValue) return;
        // Match a previous set by set_index — the "did the same set last time?"
        // comparison. The server now returns one whole session, so every index
        // present last time has an entry (story 288).
        const previousByIndex = new Map<number, StrengthSet>();
        for (const prev of this.previousByExercise) {
            if (!previousByIndex.has(prev.set_index)) {
                previousByIndex.set(prev.set_index, prev);
            }
        }

        const tracksReps = this.exerciseValue.tracks_reps === 1;
        const tracksWeight = this.exerciseValue.tracks_weight === 1;

        this.setsList.replaceChildren(...this.setsValue.map((set) => {
            const row = document.createElement('strength-set-row') as StrengthSetRow;
            row.tracksReps = tracksReps;
            row.tracksWeight = tracksWeight;
            row.set = set;
            row.previousSet = previousByIndex.get(set.set_index) ?? null;
            return row;
        }));
    }

    /**
     * The record to chase. Rendered as nothing at all when there is no history
     * — a `MAX —` line is noise, not information.
     */
    private renderMax(): void {
        if (!this.maxValue || !this.exerciseValue) {
            this.maxBtn.hidden = true;
            this.maxBtn.textContent = '';
            return;
        }
        const reps = this.maxValue.reps ?? '–';
        const weight = this.maxValue.weight_kg != null ? ` × ${this.maxValue.weight_kg}kg` : '';
        const perArm = this.exerciseValue.is_unilateral === 1 ? ' per arm' : '';
        this.maxBtn.textContent = `MAX ${reps}${weight}${perArm} · ${this.maxValue.date}`;
        this.maxBtn.hidden = false;
    }

    private renderLaterality(): void {
        if (!this.exerciseValue) return;
        const unilateral = this.exerciseValue.is_unilateral === 1;
        this.lateralityBtn.textContent = unilateral ? 'one arm' : 'both arms';
        this.lateralityBtn.setAttribute('aria-pressed', unilateral ? 'true' : 'false');
        this.lateralityBtn.classList.toggle('is-unilateral', unilateral);
    }

    /**
     * Drop the max into the first row that isn't fully logged yet — tapping a
     * record while row #1 is already done should set up row #2, not overwrite
     * what you just did. Falls back to the last row when every row is logged,
     * which is the "I want to beat it right now, add a set" case having already
     * added one.
     */
    private fillNextUnfilledFromMax(): void {
        if (!this.maxValue) return;
        const rows = Array.from(this.setsList.querySelectorAll('strength-set-row')) as StrengthSetRow[];
        if (rows.length === 0) return;
        const target = rows.find((r) => !this.isRowLogged(r)) ?? rows[rows.length - 1];
        target.fillWith({ reps: this.maxValue.reps, weight_kg: this.maxValue.weight_kg });
    }

    private isRowLogged(row: StrengthSetRow): boolean {
        return (row.shadowRoot?.querySelector('.row')?.classList.contains('logged')) ?? false;
    }

    private emitAddSet(): void {
        if (!this.exerciseValue) return;
        this.dispatchEvent(createStrengthSetAddRequestEvent({ exercise_id: this.exerciseValue.id }));
    }

    private emitRemoveExercise(): void {
        if (!this.exerciseValue) return;
        this.dispatchEvent(createExerciseRemoveFromSessionEvent({ exercise_id: this.exerciseValue.id }));
    }

    private emitLateralityToggle(): void {
        if (!this.exerciseValue) return;
        const next = this.exerciseValue.is_unilateral === 1 ? 0 : 1;
        // Optimistic: the label flips immediately and the screen reconciles
        // from the server's answer. A failed PATCH surfaces through the
        // screen's error node, so a silent revert is not needed to be honest.
        // Repaint only the two nodes that carry the flag — a full render()
        // would rebuild every row and wipe whatever is half-typed in one.
        this.exerciseValue = { ...this.exerciseValue, is_unilateral: next };
        this.renderLaterality();
        this.renderMax();
        this.dispatchEvent(createExerciseLateralityToggleEvent({
            exercise_id: this.exerciseValue.id,
            is_unilateral: next,
        }));
    }
}

if (!customElements.get('exercise-session-card')) {
    customElements.define('exercise-session-card', ExerciseSessionCard);
}
