import stylesText from './strength-set-row.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';
import type { StrengthSet, StrengthSetUpdate } from '@motivation/shared';
import {
    createStrengthSetCompleteEvent,
    createStrengthSetDeleteEvent,
    createStrengthSetEditEvent,
} from '../health-events.js';

const styles = cssStyleSheet(stylesText);

/** One international pound, exactly. The `lb→kg` button's only constant. */
const KG_PER_LB = 0.45359237;
/** Stepper increments — a rep is a rep, and 2.5 kg is the smallest plate pair. */
const REPS_STEP = 1;
const WEIGHT_STEP = 2.5;

const template = document.createElement('template');
template.innerHTML = `
    <div class="row" part="row">
        <span class="set-index" part="set-index"></span>
        <button class="previous" part="previous" type="button" hidden></button>
        <div class="fields">
            <div class="field" data-for="reps">
                <button class="step" data-step="reps-down" type="button" aria-label="one rep fewer">−</button>
                <input class="input" data-field="reps" type="number" inputmode="numeric" min="0" placeholder="reps" aria-label="reps">
                <button class="step" data-step="reps-up" type="button" aria-label="one rep more">+</button>
            </div>
            <div class="field" data-for="weight_kg">
                <button class="step" data-step="weight-down" type="button" aria-label="2.5 kilograms less">−</button>
                <input class="input" data-field="weight_kg" type="number" inputmode="decimal" min="0" step="0.5" placeholder="kg" aria-label="weight in kilograms">
                <button class="step" data-step="weight-up" type="button" aria-label="2.5 kilograms more">+</button>
                <button class="lb-convert" type="button" aria-label="convert the typed weight from pounds to kilograms">lb→kg</button>
            </div>
        </div>
        <button class="action-btn delete" type="button" aria-label="Delete set">✕</button>
    </div>
`;

/**
 * One row of an exercise card. Owns nothing — receives a `StrengthSet` and an
 * optional `previousSet` via properties, emits typed `STRENGTH_SET_*` events
 * to the screen, which does the API work and re-renders on success.
 *
 * Story 288 removed the RPE input and the ✓ button (never used). What the ✓
 * carried has been re-homed rather than dropped: the "logged" visual state is
 * now *derived* from the set's own data, so it survives a reload where the old
 * `completed` attribute did not, and the rest timer's trigger moved onto the
 * edit itself. `tracksReps` / `tracksWeight` come from the card because both
 * of those depend on which fields actually count for this exercise — a plank
 * has no weight to fill, so "all fields filled" is meaningless without them.
 */
export class StrengthSetRow extends HTMLElement {
    private setValue: StrengthSet | null = null;
    private previousValue: StrengthSet | null = null;
    private tracksRepsValue = true;
    private tracksWeightValue = true;
    private row!: HTMLElement;
    private setIndexNode!: HTMLElement;
    private previousBtn!: HTMLButtonElement;
    private repsField!: HTMLElement;
    private weightField!: HTMLElement;
    private repsInput!: HTMLInputElement;
    private weightInput!: HTMLInputElement;
    private lbConvertBtn!: HTMLButtonElement;
    private deleteBtn!: HTMLButtonElement;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        this.row = shadow.querySelector('.row') as HTMLElement;
        this.setIndexNode = shadow.querySelector('.set-index') as HTMLElement;
        this.previousBtn = shadow.querySelector('.previous') as HTMLButtonElement;
        this.repsField = shadow.querySelector('[data-for="reps"]') as HTMLElement;
        this.weightField = shadow.querySelector('[data-for="weight_kg"]') as HTMLElement;
        this.repsInput = shadow.querySelector('[data-field="reps"]') as HTMLInputElement;
        this.weightInput = shadow.querySelector('[data-field="weight_kg"]') as HTMLInputElement;
        this.lbConvertBtn = shadow.querySelector('.lb-convert') as HTMLButtonElement;
        this.deleteBtn = shadow.querySelector('.action-btn.delete') as HTMLButtonElement;

        // Listeners on own shadow DOM — attach once in the constructor so a
        // disconnect/reconnect cycle doesn't double-bind. Lifetime tracks the
        // shadow tree, so no explicit cleanup is needed.
        this.repsInput.addEventListener('change', () => this.emitEditOnChange('reps', this.repsInput.value));
        this.weightInput.addEventListener('change', () => this.emitEditOnChange('weight_kg', this.weightInput.value));
        this.previousBtn.addEventListener('click', () => this.fillFromPrevious());
        // Keep the caret in the weight field: without this the button steals
        // focus on pointerdown, the input fires `change` with the *pounds*
        // still in it, and the row persists 185 kg before the conversion runs.
        // Preventing the default focus shift also means one write, not two.
        this.lbConvertBtn.addEventListener('pointerdown', (e) => e.preventDefault());
        this.lbConvertBtn.addEventListener('click', () => this.convertTypedPoundsToKilograms());
        this.deleteBtn.addEventListener('click', () => this.emitDelete());
        for (const btn of shadow.querySelectorAll('.step')) {
            const step = (btn as HTMLElement).dataset.step!;
            btn.addEventListener('click', () => this.stepField(step));
        }
    }

    set set(value: StrengthSet) {
        this.setValue = value;
        this.setAttribute('data-set-id', value.id);
        this.render();
    }

    get set(): StrengthSet | null {
        return this.setValue;
    }

    set previousSet(value: StrengthSet | null) {
        this.previousValue = value;
        this.renderPrevious();
    }

    /** Whether this exercise logs reps at all — from the card's `Exercise`. */
    set tracksReps(value: boolean) {
        this.tracksRepsValue = value;
        this.render();
    }

    /** Whether this exercise logs a weight at all — a plank does not. */
    set tracksWeight(value: boolean) {
        this.tracksWeightValue = value;
        this.render();
    }

    connectedCallback(): void {
        this.render();
    }

    /**
     * Overwrite both inputs with concrete values and persist them, as one edit.
     * Used by the `prev:` tap here and by the card's MAX tap. Fields the
     * exercise doesn't track are left alone.
     */
    fillWith({ reps, weight_kg }: { reps?: number | null; weight_kg?: number | null }): void {
        if (!this.setValue) return;
        const wasIncomplete = !this.isLogged();
        const updates: StrengthSetUpdate = {};
        if (this.tracksRepsValue && reps != null) {
            this.repsInput.value = String(reps);
            updates.reps = reps;
        }
        if (this.tracksWeightValue && weight_kg != null) {
            this.weightInput.value = String(weight_kg);
            updates.weight_kg = weight_kg;
        }
        if (Object.keys(updates).length === 0) return;
        this.applyLocally(updates);
        this.dispatchEvent(createStrengthSetEditEvent({ set_id: this.setValue.id, updates }));
        this.renderLoggedState();
        if (wasIncomplete && this.isLogged()) this.emitComplete();
    }

    private render(): void {
        if (!this.setValue) return;
        this.setIndexNode.textContent = `#${this.setValue.set_index}`;
        this.repsInput.value = String(this.setValue.reps ?? '');
        this.weightInput.value = String(this.setValue.weight_kg ?? '');
        this.repsField.hidden = !this.tracksRepsValue;
        this.weightField.hidden = !this.tracksWeightValue;
        this.renderPrevious();
        this.renderLoggedState();
    }

    private renderPrevious(): void {
        if (!this.previousValue) {
            this.previousBtn.textContent = '';
            this.previousBtn.hidden = true;
            return;
        }
        const reps = this.previousValue.reps ?? '–';
        const w = this.previousValue.weight_kg != null ? `${this.previousValue.weight_kg}kg` : '';
        this.previousBtn.textContent = `prev: ${reps}${w ? ` × ${w}` : ''}`;
        this.previousBtn.hidden = false;
    }

    /**
     * A set is "logged" when every field this exercise tracks holds a value.
     * Derived from the set, not from an attribute a click used to set — which
     * is why the green survives a reload, and why the old ✓ is not missed.
     */
    private isLogged(): boolean {
        if (!this.setValue) return false;
        if (!this.tracksRepsValue && !this.tracksWeightValue) return false;
        if (this.tracksRepsValue && this.setValue.reps == null) return false;
        if (this.tracksWeightValue && this.setValue.weight_kg == null) return false;
        return true;
    }

    private renderLoggedState(): void {
        this.row.classList.toggle('logged', this.isLogged());
    }

    /**
     * Keep the local copy in step with what we just told the screen to persist.
     * Without this, `isLogged()` would still read the pre-edit set and the
     * "was incomplete, now complete" transition could never be observed — the
     * screen writes the authoritative value back on its own schedule.
     */
    private applyLocally(updates: StrengthSetUpdate): void {
        if (!this.setValue) return;
        if ('reps' in updates) this.setValue.reps = updates.reps ?? undefined;
        if ('weight_kg' in updates) this.setValue.weight_kg = updates.weight_kg ?? undefined;
    }

    private emitEditOnChange(field: 'reps' | 'weight_kg', raw: string): void {
        if (!this.setValue) return;
        const wasIncomplete = !this.isLogged();
        const updates: StrengthSetUpdate = {};
        if (raw === '') {
            updates[field] = null;
        } else {
            const parsed = Number(raw);
            if (!Number.isFinite(parsed) || parsed < 0) return;
            updates[field] = parsed;
        }
        this.applyLocally(updates);
        this.dispatchEvent(createStrengthSetEditEvent({ set_id: this.setValue.id, updates }));
        this.renderLoggedState();
        // Only on the incomplete → complete transition, so re-typing the same
        // weight into an already-logged row doesn't restart the rest timer.
        if (wasIncomplete && this.isLogged()) this.emitComplete();
    }

    private fillFromPrevious(): void {
        if (!this.previousValue) return;
        this.fillWith({ reps: this.previousValue.reps, weight_kg: this.previousValue.weight_kg });
    }

    /**
     * Convert whatever is currently *typed* in the weight field from pounds to
     * kilograms, in place. Storage stays `weight_kg` — this is a keypad
     * shortcut for the machines labelled in lb, not a unit mode. A blank or
     * unparseable field is a no-op rather than a silent 0.
     */
    private convertTypedPoundsToKilograms(): void {
        const raw = this.weightInput.value.trim();
        if (raw === '') return;
        const pounds = Number(raw);
        if (!Number.isFinite(pounds) || pounds < 0) return;
        const kilograms = Math.round(pounds * KG_PER_LB * 10) / 10;
        this.weightInput.value = String(kilograms);
        this.emitEditOnChange('weight_kg', this.weightInput.value);
    }

    private stepField(step: string): void {
        const isReps = step.startsWith('reps');
        const input = isReps ? this.repsInput : this.weightInput;
        const delta = (isReps ? REPS_STEP : WEIGHT_STEP) * (step.endsWith('-up') ? 1 : -1);
        const current = input.value.trim() === '' ? 0 : Number(input.value);
        if (!Number.isFinite(current)) return;
        // Clamp at 0 — a negative rep or load is not a thing, and the typed
        // path already refuses them.
        const next = Math.max(0, Math.round((current + delta) * 10) / 10);
        input.value = String(next);
        this.emitEditOnChange(isReps ? 'reps' : 'weight_kg', input.value);
    }

    private emitComplete(): void {
        if (!this.setValue) return;
        this.dispatchEvent(createStrengthSetCompleteEvent({
            set_id: this.setValue.id,
            exercise_id: this.setValue.exercise_id,
            rest_s: this.setValue.rest_s ?? null,
        }));
    }

    private emitDelete(): void {
        if (!this.setValue) return;
        this.dispatchEvent(createStrengthSetDeleteEvent({ set_id: this.setValue.id }));
    }
}

if (!customElements.get('strength-set-row')) {
    customElements.define('strength-set-row', StrengthSetRow);
}
